Circles with centres $P$ and $Q$ intersect at $A$ and $B$. $PA = 17$ cm and $PM = 8$ cm, where $M$ is the point where $PQ$ meets $AB$. Find $AB$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, angles, quotes}
\coordinate (P) at (-1,0);
\coordinate (Q) at (1,0);
\coordinate (A) at (-0.247,1.412);
\coordinate (B) at (-0.247,-1.412);
\coordinate (M) at (-0.247,0);
\draw (P) circle (1.6);
\draw (Q) circle (1.884);
\fill (P) circle (1.2pt) node[below] {$P$};
\fill (Q) circle (1.2pt) node[below] {$Q$};
\node[above] at (A) {$A$};
\node[below] at (B) {$B$};
\draw (P) -- (Q);
\draw (A) -- (B);
\draw (P) -- (A) node[midway, above left, fill=white, inner sep=1pt] {$17\text{ cm}$};
\draw (P) -- (M) node[midway, below, fill=white, inner sep=1pt] {$8\text{ cm}$};
\coordinate (Ma) at ($(M)!0.3cm!(Q)$);
\coordinate (Mb) at ($(M)!0.3cm!(B)$);
\draw (Ma) -- ($(Ma)+(Mb)-(M)$) -- (Mb);
\end{tikzpicture}
[/tikz]

In a circle of radius $13$ cm, chord $AB = 24$ cm and chord $CD = 10$ cm. Which chord is closer to the centre?
[tikz]\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, angles, quotes}
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[right] {$O$};
\coordinate (A) at (-1.846,0.769);
\coordinate (B) at (1.846,0.769);
\coordinate (C) at (-0.769,-1.846);
\coordinate (D) at (0.769,-1.846);
\coordinate (M) at (0,0.769);
\coordinate (N) at (0,-1.846);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below left] at (C) {$C$};
\node[below right] at (D) {$D$};
\draw (A) -- (B) node[midway, above, fill=white, inner sep=1pt] {$24\text{ cm}$};
