\coordinate (B) at (1.97,0.347);
\coordinate (M) at (0,0.347);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below] at (M) {$M$};
\draw (A) -- (M);
\draw (M) -- (B);
\draw (O) -- (M);
\pic[draw, "\beta", angle radius=0.45cm, angle eccentricity=2] {angle = M--O--A};
